urlPattern: R"([?&]page=gallery(&|$))";

// Exclude admin subpaths while matching everything else under /shop
urlPattern: R"(\/shop\/(?!admin).*)";

// Multiple TLDs for the same brand
urlPattern: R"(example\.(com|co\.uk|de)\/)";
